Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

$Root = (Get-Location).Path
$ExpectedBranch = "feature/vitrine-marketplace"
$MigrationRelative = "supabase\migrations\20260728224535_orcaly_mercado_pago_checkout_activation.sql"
$MigrationPath = Join-Path $Root $MigrationRelative
$BackupRoot = Join-Path $Root (".orcaly-mp-checkout-backup-" + (Get-Date -Format "yyyyMMddHHmmss"))
$PatchFile = Join-Path $env:TEMP ("orcaly-mp-checkout-" + [Guid]::NewGuid().ToString("N") + ".js")
$Utf8 = New-Object System.Text.UTF8Encoding($false)

$ExistingFiles = @(
  "app\api\marketplace\payments\mercado-pago\callback\route.ts",
  "app\api\marketplace\payments\mercado-pago\disconnect\route.ts",
  "app\api\marketplace\payments\settings\route.ts",
  "app\api\public-site\[slug]\route.ts",
  "lib\payments\checkout-service.ts",
  "components\checkout\CheckoutClient.tsx",
  "components\painel\MarketplacePaymentsPanel.tsx",
  "app\api\marketplace\payments\webhook\mercado-pago\route.ts"
)

$TouchedFiles = @(
  $ExistingFiles + $MigrationRelative
)

function Write-Base64File {
  param(
    [Parameter(Mandatory = $true)][string]$Path,
    [Parameter(Mandatory = $true)][string]$Base64
  )

  $Bytes = [Convert]::FromBase64String(($Base64 -replace "\s", ""))
  $Content = [Text.Encoding]::UTF8.GetString($Bytes)

  New-Item -ItemType Directory -Force -Path (Split-Path $Path -Parent) | Out-Null
  [IO.File]::WriteAllText($Path, $Content.TrimEnd() + "`n", $Utf8)
}

function Restore-OrcalyBackup {
  Write-Host ""
  Write-Host "Restaurando os arquivos anteriores..." -ForegroundColor Yellow

  foreach ($Relative in $ExistingFiles) {
    $Source = Join-Path $BackupRoot $Relative
    $Destination = Join-Path $Root $Relative

    if (Test-Path -LiteralPath $Source) {
      New-Item -ItemType Directory -Force -Path (Split-Path $Destination -Parent) | Out-Null
      Copy-Item -LiteralPath $Source -Destination $Destination -Force
    }
  }

  $MigrationBackup = Join-Path $BackupRoot $MigrationRelative

  if (Test-Path -LiteralPath $MigrationBackup) {
    New-Item -ItemType Directory -Force -Path (Split-Path $MigrationPath -Parent) | Out-Null
    Copy-Item -LiteralPath $MigrationBackup -Destination $MigrationPath -Force
  }
  elseif (Test-Path -LiteralPath $MigrationPath) {
    Remove-Item -LiteralPath $MigrationPath -Force
  }
}

if (-not (Test-Path -LiteralPath (Join-Path $Root "package.json"))) {
  throw "Execute este script na raiz do projeto Orçaly."
}

$Branch = (& git branch --show-current | Out-String).Trim()

if ($Branch -ne $ExpectedBranch) {
  throw "Branch atual: $Branch. Use $ExpectedBranch."
}

foreach ($Relative in $ExistingFiles) {
  $Path = Join-Path $Root $Relative

  if (-not (Test-Path -LiteralPath $Path)) {
    throw "Arquivo obrigatório não encontrado: $Relative"
  }
}

New-Item -ItemType Directory -Force -Path $BackupRoot | Out-Null

foreach ($Relative in $ExistingFiles) {
  $Source = Join-Path $Root $Relative
  $Destination = Join-Path $BackupRoot $Relative

  New-Item -ItemType Directory -Force -Path (Split-Path $Destination -Parent) | Out-Null
  Copy-Item -LiteralPath $Source -Destination $Destination -Force
}

if (Test-Path -LiteralPath $MigrationPath) {
  $MigrationBackup = Join-Path $BackupRoot $MigrationRelative
  New-Item -ItemType Directory -Force -Path (Split-Path $MigrationBackup -Parent) | Out-Null
  Copy-Item -LiteralPath $MigrationPath -Destination $MigrationBackup -Force
}

try {
  Write-Host "==> Ativando checkout transparente Mercado Pago - R2" -ForegroundColor Cyan

  Write-Base64File `
    -Path $PatchFile `
    -Base64 @'

'@

  Write-Base64File `
    -Path $MigrationPath `
    -Base64 @'

'@

  Push-Location $Root

  try {
    & node $PatchFile
    $PatchExitCode = $LASTEXITCODE
  }
  finally {
    Pop-Location
  }

  Write-Host ""
  Write-Host "PATCH_NODE_EXIT_CODE=$PatchExitCode" -ForegroundColor Yellow

  if ($PatchExitCode -ne 0) {
    throw "O patch Node falhou."
  }

  $Checks = @(
    @("app\api\marketplace\payments\mercado-pago\callback\route.ts", "ORCALY_MP_AUTO_ENABLE_V1"),
    @("app\api\marketplace\payments\mercado-pago\callback\route.ts", "charges_enabled: true"),
    @("app\api\marketplace\payments\mercado-pago\disconnect\route.ts", "charges_enabled: false"),
    @("app\api\public-site\[slug]\route.ts", "ORCALY_PUBLIC_MP_CHECKOUT_V1"),
    @("app\api\public-site\[slug]\route.ts", "marketplace_payment_provider: mercadoPagoConnected ? 'mercado_pago' : null"),
    @("lib\payments\checkout-service.ts", "ORCALY_MP_TRANSPARENT_CHECKOUT_V1"),
    @("lib\payments\checkout-service.ts", '.from("marketplace_coupons")'),
    @("lib\payments\checkout-service.ts", "publicKey: connected"),
    @("lib\payments\checkout-service.ts", "consume_marketplace_coupon"),
    @("components\checkout\CheckoutClient.tsx", "ORCALY_SELLER_PUBLIC_KEY_V1"),
    @("components\checkout\CheckoutClient.tsx", "fallbackPublicKey"),
    @("components\checkout\CheckoutClient.tsx", "data?.payment.publicKey"),
    @("components\painel\MarketplacePaymentsPanel.tsx", "Pix ativo"),
    @("app\api\marketplace\payments\webhook\mercado-pago\route.ts", "ORCALY_COUPON_USAGE_WEBHOOK_V1"),
    @($MigrationRelative, "ORCALY_MERCADO_PAGO_CHECKOUT_ACTIVATION_V1")
  )

  Write-Host ""
  Write-Host "==> Verificando marcadores" -ForegroundColor Cyan

  foreach ($Check in $Checks) {
    $Relative = $Check[0]
    $Pattern = $Check[1]
    $Path = Join-Path $Root $Relative

    $Match = Select-String `
      -LiteralPath $Path `
      -Pattern $Pattern `
      -SimpleMatch `
      -ErrorAction SilentlyContinue

    if (-not $Match) {
      throw "Verificação falhou: $Relative -> $Pattern"
    }

    Write-Host "[OK] $Relative -> $Pattern" -ForegroundColor Green
  }

  Write-Host ""
  Write-Host "==> Verificando diff" -ForegroundColor Cyan

  & git diff --check -- @($TouchedFiles)

  if ($LASTEXITCODE -ne 0) {
    throw "git diff --check encontrou problemas."
  }

  if (Test-Path -LiteralPath (Join-Path $Root ".next")) {
    Remove-Item -LiteralPath (Join-Path $Root ".next") -Recurse -Force
  }

  Write-Host ""
  Write-Host "==> Executando build completo" -ForegroundColor Cyan

  & npm run build
  $BuildExitCode = $LASTEXITCODE

  Write-Host ""
  Write-Host "BUILD_EXIT_CODE=$BuildExitCode" -ForegroundColor Yellow

  if ($BuildExitCode -ne 0) {
    throw "O build falhou."
  }

  Remove-Item -LiteralPath $BackupRoot -Recurse -Force

  Write-Host ""
  Write-Host "==================================================" -ForegroundColor Magenta
  Write-Host "CHECKOUT MERCADO PAGO ATIVADO E APROVADO - R2" -ForegroundColor Magenta
  Write-Host "==================================================" -ForegroundColor Magenta
  Write-Host "OAuth conectado: libera o checkout automaticamente"
  Write-Host "Meios: Pix, crédito e débito"
  Write-Host "Cálculo: produtos + opções - cupom + frete"
  Write-Host "Cupom: percentual, fixo e frete grátis"
  Write-Host "Public Key: carregada por vendedor via OAuth"
  Write-Host "Migration local: $MigrationRelative"
  Write-Host ""
  Write-Host "A migration remota já foi aplicada e validada."
  Write-Host "Nenhum commit, push ou deploy foi criado."
}
catch {
  Restore-OrcalyBackup
  throw
}
finally {
  if (Test-Path -LiteralPath $PatchFile) {
    Remove-Item -LiteralPath $PatchFile -Force
  }
}
